SELECT tags, timestamp, value FROM (SELECT series.tags AS tags, max(d.timestamp) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
    SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {sort_child_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({sort_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({sort_child_required_end_ms:Int64})
) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({sort_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({sort_child_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags) AS sort_child ORDER BY isNaN(sort_child.value) ASC, sort_child.value ASC, sort_child.tags ASC, sort_child.timestamp ASC
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
